def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}  # name -> [balance, frozen]
    history = []   # each entry: list of inverse actions for one successful op
    rejected = []

    def is_amount(tok):
        return len(tok) > 0 and all('0' <= c <= '9' for c in tok)

    for i, op in enumerate(ops):
        parts = op.split(" ")
        verb, args = parts[0], parts[1:]
        inverse = None

        if verb == "open" and len(args) == 2:
            a, n = args
            if is_amount(n) and a not in accounts:
                accounts[a] = [int(n), False]
                inverse = [("del", a)]

        elif verb == "deposit" and len(args) == 2:
            a, n = args
            if is_amount(n) and int(n) > 0 and a in accounts:
                amt = int(n)
                accounts[a][0] += amt
                inverse = [("bal", a, -amt)]

        elif verb == "withdraw" and len(args) == 2:
            a, n = args
            if is_amount(n) and int(n) > 0 and a in accounts:
                amt = int(n)
                acc = accounts[a]
                if not acc[1] and acc[0] >= amt:
                    acc[0] -= amt
                    inverse = [("bal", a, amt)]

        elif verb == "transfer" and len(args) == 3:
            a, b, n = args
            if (is_amount(n) and int(n) > 0 and a != b
                    and a in accounts and b in accounts):
                amt = int(n)
                src = accounts[a]
                if not src[1] and src[0] >= amt:
                    src[0] -= amt
                    accounts[b][0] += amt
                    inverse = [("bal", a, amt), ("bal", b, -amt)]

        elif verb == "freeze" and len(args) == 1:
            a = args[0]
            if a in accounts and not accounts[a][1]:
                accounts[a][1] = True
                inverse = [("frz", a, False)]

        elif verb == "unfreeze" and len(args) == 1:
            a = args[0]
            if a in accounts and accounts[a][1]:
                accounts[a][1] = False
                inverse = [("frz", a, True)]

        elif verb == "undo" and len(args) == 0:
            if history:
                for action in history.pop():
                    kind = action[0]
                    if kind == "del":
                        del accounts[action[1]]
                    elif kind == "bal":
                        accounts[action[1]][0] += action[2]
                    elif kind == "frz":
                        accounts[action[1]][1] = action[2]
                # undo itself is never recorded, so it cannot be reverted
                continue

        if inverse is None:
            rejected.append(i)
        else:
            history.append(inverse)

    balances = {name: acc[0] for name, acc in accounts.items()}
    return balances, rejected
